function drawMap(x: number, y: number, w: number, h: number, dots: { lon: number; lat: number; n: number }[]): void {
  fillRect(x, y, w, h, SEA);
  // graticule
  for (let lon = -150; lon <= 150; lon += 30) {
    strokeLine(x + ((lon + 180) / 360) * w, y, x + ((lon + 180) / 360) * w, y + h, 0.7, [160, 190, 184]);
  }
  for (let lat = -60; lat <= 60; lat += 30) {
    strokeLine(x, y + ((85 - lat) / 145) * h, x + w, y + ((85 - lat) / 145) * h, 0.7, [160, 190, 184]);
  }
  const proj = (lon: number, lat: number): Pt => [
    x + ((lon + 180) / 360) * w,
    y + ((85 - lat) / 145) * h,
  ];
  for (const cont of CONTINENTS) {
    const pts = cont.map(([lon, lat]) => proj(lon, lat));
    fillPoly(pts, LAND);
    polyline(pts, 1, [150, 138, 110], true);
  }
  // small islands
  const [ukx, uky] = proj(-2, 54);
  fillEllipse(ukx, uky, 3, 5, LAND);
  const [jpx, jpy] = proj(140, 38);
  fillEllipse(jpx, jpy, 3, 7, LAND);
  const [idx, idy] = proj(115, -2);
  fillEllipse(idx, idy, 9, 3, LAND);
  const [nzx, nzy] = proj(172, -42);
  fillEllipse(nzx, nzy, 3, 6, LAND);
  for (const d of dots) {
    const [dx, dy] = proj(d.lon, d.lat);
    numBadge(dx, dy, d.n, 10);
  }
}

